SourceCode.Declaration:
/// <summary>
/// CB223_PalletRounding
/// Pallet rounding logic for a sales order line.
/// </summary>
internal final class METSalesLinePalletRoundingProcess
{
    SalesId         salesId;
    ItemId          itemId;
    CustAccount     custAccount;
    SalesUnit       salesUnit;
    SalesQty        salesQtySum;
    InventSiteId    inventSiteId;
    InventDimId     inventDimId;

    METInventItemOrderSetup metInventItemOrderSetup;

}

Method.Source:
/// <summary>
/// Construct
/// </summary>
/// <param name = "_salesId">Sales order id</param>
/// <param name = "_itemId">Item number</param>
/// <param name = "_custAccount">Customer account</param>
/// <param name = "_salesUnit">Sales order line UOM</param>
/// <param name = "_salesQtySum">Sum of qty for the same item in the SO</param>
/// <param name = "_inventDimId">Inventory dimension id</param>
/// <param name = "_inventSiteId">Site</param>
/// <returns>New instance of <c>METSalesLinePalletRoundingProcess</c> class</returns>
static METSalesLinePalletRoundingProcess construct(SalesId      _salesId,
                                                   ItemId       _itemId,
                                                   CustAccount  _custAccount,
                                                   SalesUnit    _salesUnit,
                                                   SalesQty     _salesQtySum,
                                                   InventDimId  _inventDimId,
                                                   InventSiteId _inventSiteId)
{
    if (!_salesId || !_itemId || !_custAccount || !_salesUnit || !_salesQtySum || !_inventDimId || !_inventSiteId)
    {
        throw error(strFmt("@SYS19306", funcName()));
    }

    return new METSalesLinePalletRoundingProcess(_salesId, _itemId, _custAccount, _salesUnit, _salesQtySum, _inventDimId, _inventSiteId);
}

/// <summary>
/// New method
/// </summary>
/// <param name = "_salesId">Sales order id</param>
/// <param name = "_itemId">Item number</param>
/// <param name = "_custAccount">Customer account</param>
/// <param name = "_salesUnit">Sales order line UOM</param>
/// <param name = "_salesQtySum">Sum of qty for the same item in the SO</param>
/// <param name = "_inventDimId">Inventory dimension id</param>
/// <param name = "_inventSiteId">Site</param>
protected void new(SalesId      _salesId,
                   ItemId       _itemId,
                   CustAccount  _custAccount,
                   SalesUnit    _salesUnit,
                   SalesQty     _salesQtySum,
                   InventDimId  _inventDimId,
                   InventSiteId _inventSiteId)
{
    salesId         = _salesId;
    itemId          = _itemId;
    custAccount     = _custAccount;
    salesUnit       = _salesUnit;
    salesQtySum     = _salesQtySum;
    inventDimId     = _inventDimId;
    inventSiteId    = _inventSiteId;
}

/// <summary>
/// Run the sales order line pallet rounding
/// </summary>
/// <returns>True if the line was processed, even if no pallet rounding policy; otherwise, returns false if validation failed.</returns>
boolean run()
{
    boolean processed = true;

    // Check 1: The sales order line site, item and customer match an active pallet rounding policy.
    METPalletRoundingPolicySearch search = METPalletRoundingPolicySearch::construct(custAccount, inventSiteId, itemId);
    METPalletRoundingPolicyLine palletRoundingPolicyLine = search.search();

    if (palletRoundingPolicyLine)
    {
        // retrieve default order settings
        metInventItemOrderSetup = METInventItemOrderSetup::findByItemAndSite(itemId, inventSiteId);

        // validate
        if (this.validate())
        {
            // round up quantities
            this.palletRoundUp(palletRoundingPolicyLine);
        }
        else
        {
            processed = false;
        }
    }

    return processed;
}

/// <summary>
/// Roundup sales order line qty to pallet
/// </summary>
/// <param name = "_palletRoundingPolicyLine">Pallet rounding policy line</param>
void palletRoundUp(METPalletRoundingPolicyLine _palletRoundingPolicyLine)
{        
    InventQty salesLineInventQty;
    UnitOfMeasureSymbol inventUnitId = InventTableModule::find(this.ItemId, ModuleInventPurchSales::Invent).UnitId;

    // Check 3: Convert the Sales order line(s) quantity into the Inventory Unit of measure.
    salesLineInventQty = EcoResProductUnitConverter::convertForReleasedProduct(this.ItemId,
                                                                               this.inventDimId,
                                                                               salesQtySum,
                                                                               UnitOfMeasure::unitOfMeasureIdBySymbol(salesUnit),
                                                                               UnitOfMeasure::unitOfMeasureIdBySymbol(inventUnitId));

    InventQty modQty = salesLineInventQty mod metInventItemOrderSetup.PalletQty;

    // Check 4: If the result percentage is equal or greater than the percentage defined in the pallet rounding policy, round up will be applied to the sales order line
    if (((modQty * 100)  / metInventItemOrderSetup.PalletQty) >= _palletRoundingPolicyLine.RoundingPercentage)
    {
        // Update sales order line fields
        // If above checks are successful, apply the pallet rounding.
        // Convert the new quantity from the item's inventory unit of measure to the sales order unit of measure and apply it to the original sales order line (not on the bonus stock line).
        InventQty salesLineRoundedInventQty = salesLineInventQty + metInventItemOrderSetup.PalletQty - modQty;
        InventQty salesLineDiffInventQty = salesLineRoundedInventQty - salesLineInventQty;

        SalesQty salesLineRoundedSalesQty = EcoResProductUnitConverter::convertForReleasedProduct(this.ItemId,
                                                                                   this.inventDimId,
                                                                                   salesLineDiffInventQty,
                                                                                   UnitOfMeasure::unitOfMeasureIdBySymbol(inventUnitId),
                                                                                   UnitOfMeasure::unitOfMeasureIdBySymbol(salesUnit));

        ttsbegin;
        // find the original sales line (not the bonus stock one)
        SalesLine salesLine = SalesLine::metFindBonusStock(salesId, itemId, custAccount, salesUnit, inventDimId, NoYes::No, true);

        if (salesLine)
        {
            SalesQty origSalesQty = salesLine.SalesQty;

            // round up to pallet qty
            salesLine.SalesQty += salesLineRoundedSalesQty;

            // very important to call this to update inventTrans qty and remainder qty
            salesLine.salesQtyModified();
            salesLine.update();

            METSalesLine metSalesLine = METSalesLine::find(salesLine.RecId, true);

            if (metSalesLine)
            {
                metSalesLine.PalletRoundingApplied              = NoYes::Yes;
                metSalesLine.PalletRoundingOriginalQty          = origSalesQty;
                metSalesLine.PalletRoundingPolicyLineRefRecId   = _palletRoundingPolicyLine.RecId;
                metSalesLine.PalletRoundingPercentage           = _palletRoundingPolicyLine.RoundingPercentage;

                metSalesLine.update();
            }
            else
            {
                throw error(strFmt("@MET:PalletRoundingMETSalesLineError", salesId,
                                                                           itemId, 
                                                                           custAccount, 
                                                                           salesUnit, 
                                                                           inventDimId));
            }
        }
        else
        {
            throw error(strFmt("@MET:PalletRoundingSalesLineError", salesLine.RecId));
        }
        ttscommit;
    }
}

/// <summary>
/// Validate substitution before executing it
/// </summary>
/// <returns>True if validation successful; otherwise, false</returns>
protected boolean validate()
{
    boolean ret = true;

    if (!metInventItemOrderSetup)
    {
        ret = checkFailed(strFmt("@MET:PalletRoundingInventItemOrderSetupError", itemId, inventSiteId));
    }
    else if (!metInventItemOrderSetup.PalletQty)
    {
        ret = checkFailed(strFmt("@MET:PalletRoundingInventItemOrderSetupPalletQtyError", fieldPName(METInventItemOrderSetup, PalletQty), itemId, inventSiteId));
    }

    return ret;
}
